def org_schema():
    area=['South Wales','Cardiff','Swansea','Newport','Bridgend','Vale of Glamorgan','Rhondda Cynon Taf','Caerphilly','Merthyr Tydfil','Neath Port Talbot','Torfaen','Blaenau Gwent','Monmouthshire','Carmarthenshire']
    return {'@type':'EducationalOrganization','@id':BASE+'#organization','name':'South Wales Tutoring','url':BASE,'logo':BASE+'assets/brand/swt-logo.svg','image':BASE+'assets/images/social-share.png','description':'One-to-one online WJEC GCSE, A-Level, KS3 and primary tutoring across South Wales in Maths, Physics, Chemistry, Biology, English and Science.','telephone':'+447480231362','email':'southwales@nwttutoring.com','areaServed':[{'@type':'Place','name':a} for a in area],'parentOrganization':{'@type':'Organization','name':'North Wales Tutoring Group','url':'https://nwttutoring.com/'},'sameAs':['https://www.facebook.com/southwalestutoring/','https://www.instagram.com/southwalestutoring/'],'contactPoint':{'@type':'ContactPoint','telephone':'+447480231362','email':'southwales@nwttutoring.com','contactType':'customer support','availableLanguage':['English']}}
def structured(path,title,description,crumbs=None,faq=None,service=None,article=None):
    url=BASE+path if path!='index.html' else BASE
    obj={'@context':'https://schema.org','@graph':[org_schema(),{'@type':'WebSite','@id':BASE+'#website','name':'South Wales Tutoring','url':BASE,'publisher':{'@id':BASE+'#organization'}},{'@type':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':description,'isPartOf':{'@id':BASE+'#website'},'about':{'@id':BASE+'#organization'},'inLanguage':'en-GB'}]}
    if crumbs:
        elems=[{'@type':'ListItem','position':1,'name':'Home','item':BASE}]
        for i,(label,ref) in enumerate(crumbs,2):elems.append({'@type':'ListItem','position':i,'name':label,'item':BASE+ref})
        obj['@graph'].append({'@type':'BreadcrumbList','itemListElement':elems})
    if faq:
        def strip(s): return re.sub(r'<[^>]+>','',s)
        obj['@graph'].append({'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':html.unescape(strip(a))}} for q,a in faq]})
    if service:
        obj['@graph'].append({'@type':'Service','name':service.get('name',title),'description':service.get('desc',description),'serviceType':'Live one-to-one online tutoring','provider':{'@id':BASE+'#organization'},'areaServed':org_schema()['areaServed'],'audience':{'@type':'EducationalAudience','educationalRole':'student'},'offers':{'@type':'Offer','priceCurrency':'GBP','price':service.get('price',20),'description':'Starting hourly rate. Subject and tutor availability are confirmed upon enquiry.'}})
    if article:
        obj['@graph'].append({'@type':'BlogPosting','headline':title,'description':description,'mainEntityOfPage':{'@id':url+'#webpage'},'image':BASE+'assets/images/'+article.get('image','social-share.png'),'datePublished':article.get('date',DATE),'dateModified':article.get('date',DATE),'author':{'@type':'Organization','name':'South Wales Tutoring'},'publisher':{'@id':BASE+'#organization'}})
    return obj

def render(path,title,description,body,crumbs=None,faq=None,service=None,article=None,blog_css=False,noindex=False):
    depth=path.count('/'); rel='../'*depth or './'
    url=BASE if path=='index.html' else BASE+path
    social=BASE+'assets/images/social-share.png'
    data=structured(path,title,description,crumbs,faq,service,article)
    # Breadcrumb HTML, content links, assets and resources are statically scoped relative to folder.
    body=body.replace('{B}',rel)
    meta=f'''<!doctype html><html lang="en-GB"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#09096a"><meta name="site-base" content="{rel}">
<title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="{esc(url)}"><link rel="alternate" href="{esc(url)}" hreflang="en-GB">
<meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:site_name" content="South Wales Tutoring"><meta property="og:locale" content="en_GB"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{esc(url)}"><meta property="og:image" content="{social}"><meta property="og:image:alt" content="South Wales Tutoring, online GCSE and A-Level tutors"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(description)}"><meta name="twitter:image" content="{social}">
<link rel="icon" type="image/svg+xml" href="{rel}assets/brand/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="{rel}assets/css/global.css"><link rel="stylesheet" href="{rel}assets/css/pages.css">{f'<link rel="stylesheet" href="{rel}assets/css/blog.css">' if blog_css else ''}
<script type="application/ld+json">{json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')}</script>
<script src="{rel}assets/js/components.js" defer></script><script src="{rel}assets/js/site.js" defer></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js" defer></script>{f'<script src="{rel}assets/js/blog.js" defer></script>' if path=='blog.html' else ''}
</head><body><site-header></site-header><main id="main">{body}</main><site-footer></site-footer><cookie-consent></cookie-consent></body></html>'''
    target=ROOT/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(meta,encoding='utf-8')
    if not noindex:PAGES.append((path,DATE))

